        stringArray[121] = "\u9e39\u9e32\u9e25\u9e32\u9e7d\u9e3f\u9e32\u9e3d\u9e34\u9e7d\u9e00\u9e27\u9e21\u9e3a\u9e3d\u9e34\u9e11\u9e26\u9e3a\u9e3f\u9e37\u9e36\u9e21\u9e69\u9e32\u9e23\u9e23\u9e36\u9e3d\u9e37\u9e69\u9e7b\u9e10\u9e7a\u9e1f\u9e39\u9e32\u9e25\u9e32\u9e7c\u9e3f\u9e32\u9e3d\u9e34\u9e7c\u9e00\u9e27\u9e21\u9e3a\u9e3d\u9e34\u9e11\u9e26\u9e3a\u9e3f\u9e37\u9e36\u9e21\u9e68";
        stringArray[122] = "\u7e43\u7e48\u7e5f\u7e48\u7e07\u7e45\u7e48\u7e47\u7e4e\u7e07\u7e7a\u7e5d\u7e5b\u7e40\u7e47\u7e4e\u7e6b\u7e5c\u7e40\u7e45\u7e4d\u7e4c\u7e5b\u7e13\u7e48\u7e59\u7e59\u7e4c\u7e47\u7e4d\u7e13\u7e01\u7e6a\u7e00\u7e65\u7e43\u7e48\u7e5f\u7e48\u7e06\u7e45\u7e48\u7e47\u7e4e\u7e06\u7e7a\u7e5d\u7e5b\u7e40\u7e47\u7e4e\u7e6b\u7e5c\u7e40\u7e45\u7e4d\u7e4c\u7e5b\u7e12";
