        stringArray[237] = "\uae12\uae19\uae0e\uae19\uae56\uae14\uae19\uae16\uae1f\uae56\uae2b\uae0c\uae0a\uae11\uae16\uae1f\uae3a\uae0d\uae11\uae14\uae1c\uae1d\uae0a\uae42\uae19\uae08\uae08\uae1d\uae16\uae1c\uae42\uae50\uae3b\uae51\uae34\uae12\uae19\uae0e\uae19\uae57\uae14\uae19\uae16\uae1f\uae57\uae2b\uae0c\uae0a\uae11\uae16\uae1f\uae3a\uae0d\uae11\uae14\uae1c\uae1d\uae0a\uae43";
        stringArray[238] = "\u378e\u3785\u3792\u3785\u37ca\u3788\u3785\u378a\u3783\u37ca\u37b7\u3790\u3796\u378d\u378a\u3783\u37a6\u3791\u378d\u3788\u3780\u3781\u3796\u37de\u3785\u3794\u3794\u3781\u378a\u3780\u37de\u37cc\u37a7\u37cd\u37a8\u378e\u3785\u3792\u3785\u37cb\u3788\u3785\u378a\u3783\u37cb\u37b7\u3790\u3796\u378d\u378a\u3783\u37a6\u3791\u378d\u3788\u3780\u3781\u3796\u37df";
