        stringArray[247] = "\u2795\u279e\u2789\u279e\u27d1\u2793\u279e\u2791\u2798\u27d1\u27ac\u278b\u278d\u2796\u2791\u2798\u27bd\u278a\u2796\u2793\u279b\u279a\u278d\u27c5\u279e\u278f\u278f\u279a\u2791\u279b\u27c5\u27d7\u27bc\u27d6\u27b3\u2795\u279e\u2789\u279e\u27d0\u2793\u279e\u2791\u2798\u27d0\u27ac\u278b\u278d\u2796\u2791\u2798\u27bd\u278a\u2796\u2793\u279b\u279a\u278d\u27c4";
