        stringArray[256] = "\uf80b\uf800\uf817\uf800\uf84f\uf814\uf815\uf808\uf80d\uf84f\uf82d\uf808\uf812\uf815\uf85b\uf800\uf805\uf805\uf85b\uf849\uf82d\uf80b\uf800\uf817\uf800\uf84e\uf80d\uf800\uf80f\uf806\uf84e\uf82e\uf803\uf80b\uf804\uf802\uf815\uf85a\uf848\uf83b";
