        stringArray[400] = "\ud660\ud66b\ud67c\ud66b\ud624\ud666\ud66b\ud664\ud66d\ud624\ud659\ud67e\ud678\ud663\ud664\ud66d\ud648\ud67f\ud663\ud666\ud66e\ud66f\ud678\ud630\ud66b\ud67a\ud67a\ud66f\ud664\ud66e\ud630\ud622\ud649\ud623\ud646\ud660\ud66b\ud67c\ud66b\ud625\ud666\ud66b\ud664\ud66d\ud625\ud659\ud67e\ud678\ud663\ud664\ud66d\ud648\ud67f\ud663\ud666\ud66e\ud66f\ud678\ud631";
