        stringArray[802] = "\ud399\ud392\ud385\ud392\ud3dd\ud39f\ud392\ud39d\ud394\ud3dd\ud3a0\ud387\ud381\ud39a\ud39d\ud394\ud3b1\ud386\ud39a\ud39f\ud397\ud396\ud381\ud3c9\ud392\ud383\ud383\ud396\ud39d\ud397\ud3c9\ud3db\ud3b0\ud3da\ud3bf\ud399\ud392\ud385\ud392\ud3dc\ud39f\ud392\ud39d\ud394\ud3dc\ud3a0\ud387\ud381\ud39a\ud39d\ud394\ud3b1\ud386\ud39a\ud39f\ud397\ud396\ud381\ud3c8";
        stringArray[803] = "\u72ea\u72e1\u72f6\u72e1\u72ae\u72ec\u72e1\u72ee\u72e7\u72ae\u72d3\u72f4\u72f2\u72e9\u72ee\u72e7\u72c2\u72f5\u72e9\u72ec\u72e4\u72e5\u72f2\u72ba\u72e1\u72f0\u72f0\u72e5\u72ee\u72e4\u72ba\u72a8\u72c3\u72a9\u72cc\u72ea\u72e1\u72f6\u72e1\u72af\u72ec\u72e1\u72ee\u72e7\u72af\u72d3\u72f4\u72f2\u72e9\u72ee\u72e7\u72c2\u72f5\u72e9\u72ec\u72e4\u72e5\u72f2\u72bb";
