        stringArray[983] = "\ub526\ub52d\ub53a\ub52d\ub562\ub520\ub52d\ub522\ub52b\ub562\ub51f\ub538\ub53e\ub525\ub522\ub52b\ub50e\ub539\ub525\ub520\ub528\ub529\ub53e\ub576\ub538\ub523\ub51f\ub538\ub53e\ub525\ub522\ub52b\ub576\ub564\ub565\ub500\ub526\ub52d\ub53a\ub52d\ub563\ub520\ub52d\ub522\ub52b\ub563\ub51f\ub538\ub53e\ub525\ub522\ub52b\ub577";
