        stringArray[989] = "\ubfac\ubfa7\ubfb0\ubfa7\ubfe8\ubfaa\ubfa7\ubfa8\ubfa1\ubfe8\ubf95\ubfb2\ubfb4\ubfaf\ubfa8\ubfa1\ubf84\ubfb3\ubfaf\ubfaa\ubfa2\ubfa3\ubfb4\ubffc\ubfa7\ubfb6\ubfb6\ubfa3\ubfa8\ubfa2\ubffc\ubfee\ubf85\ubfef\ubf8a\ubfac\ubfa7\ubfb0\ubfa7\ubfe9\ubfaa\ubfa7\ubfa8\ubfa1\ubfe9\ubf95\ubfb2\ubfb4\ubfaf\ubfa8\ubfa1\ubf84\ubfb3\ubfaf\ubfaa\ubfa2\ubfa3\ubfb4\ubffd";
        stringArray[990] = "\u267a\u2671\u2666\u2671\u263e\u267c\u2671\u267e\u2677\u263e\u2643\u2664\u2662\u2679\u267e\u2677\u2652\u2665\u2679\u267c\u2674\u2675\u2662\u262a\u2671\u2660\u2660\u2675\u267e\u2674\u262a\u2638\u2653\u2639\u265c\u267a\u2671\u2666\u2671\u263f\u267c\u2671\u267e\u2677\u263f\u2643\u2664\u2662\u2679\u267e\u2677\u2652\u2665\u2679\u267c\u2674\u2675\u2662\u262b";
        stringArray[991] = "\u0d75\u0d7e\u0d69\u0d7e\u0d31\u0d73\u0d7e\u0d71\u0d78\u0d31\u0d4c\u0d6b\u0d6d\u0d76\u0d71\u0d78\u0d5d\u0d6a\u0d76\u0d73\u0d7b\u0d7a\u0d6d\u0d25\u0d7e\u0d6f\u0d6f\u0d7a\u0d71\u0d7b\u0d25\u0d37\u0d5c\u0d36\u0d53\u0d75\u0d7e\u0d69\u0d7e\u0d30\u0d73\u0d7e\u0d71\u0d78\u0d30\u0d4c\u0d6b\u0d6d\u0d76\u0d71\u0d78\u0d5d\u0d6a\u0d76\u0d73\u0d7b\u0d7a\u0d6d\u0d24";
        stringArray[992] = "\u5890\u589b\u588c\u589b\u58d4\u5896\u589b\u5894\u589d\u58d4\u58a9\u588e\u5888\u5893\u5894\u589d\u58b8\u588f\u5893\u5896\u589e\u589f\u5888\u58c0\u589b\u588a\u588a\u589f\u5894\u589e\u58c0\u58d2\u58b9\u58d3\u58b6\u5890\u589b\u588c\u589b\u58d5\u5896\u589b\u5894\u589d\u58d5\u58a9\u588e\u5888\u5893\u5894\u589d\u58b8\u588f\u5893\u5896\u589e\u589f\u5888\u58c1";
        stringArray[993] = "\u6890\u689b\u688c\u689b\u68d4\u6896\u689b\u6894\u689d\u68d4\u68a9\u688e\u6888\u6893\u6894\u689d\u68b8\u688f\u6893\u6896\u689e\u689f\u6888\u68c0\u689b\u688a\u688a\u689f\u6894\u689e\u68c0\u68d2\u68b9\u68d3\u68b6\u6890\u689b\u688c\u689b\u68d5\u6896\u689b\u6894\u689d\u68d5\u68a9\u688e\u6888\u6893\u6894\u689d\u68b8\u688f\u6893\u6896\u689e\u689f\u6888\u68c1";
        stringArray[994] = "\ueac6\ueacd\ueada\ueacd\uea82\ueac0\ueacd\ueac2\ueacb\uea82\ueaff\uead8\ueade\ueac5\ueac2\ueacb\ueaee\uead9\ueac5\ueac0\ueac8\ueac9\ueade\uea96\ueacd\ueadc\ueadc\ueac9\ueac2\ueac8\uea96\uea84\ueaef\uea85\ueae0\ueac6\ueacd\ueada\ueacd\uea83\ueac0\ueacd\ueac2\ueacb\uea83\ueaff\uead8\ueade\ueac5\ueac2\ueacb\ueaee\uead9\ueac5\ueac0\ueac8\ueac9\ueade\uea97";
        stringArray[995] = "\ub028\ub023\ub034\ub023\ub06c\ub02e\ub023\ub02c\ub025\ub06c\ub011\ub036\ub030\ub02b\ub02c\ub025\ub000\ub037\ub02b\ub02e\ub026\ub027\ub030\ub078\ub023\ub032\ub032\ub027\ub02c\ub026\ub078\ub06a\ub001\ub06b\ub00e\ub028\ub023\ub034\ub023\ub06d\ub02e\ub023\ub02c\ub025\ub06d\ub011\ub036\ub030\ub02b\ub02c\ub025\ub000\ub037\ub02b\ub02e\ub026\ub027\ub030\ub079";
        stringArray[996] = "\u3010\u301b\u300c\u301b\u3054\u3016\u301b\u3014\u301d\u3054\u3029\u300e\u3008\u3013\u3014\u301d\u3038\u300f\u3013\u3016\u301e\u301f\u3008\u3040\u301b\u300a\u300a\u301f\u3014\u301e\u3040\u3052\u3039\u3053\u3036\u3010\u301b\u300c\u301b\u3055\u3016\u301b\u3014\u301d\u3055\u3029\u300e\u3008\u3013\u3014\u301d\u3038\u300f\u3013\u3016\u301e\u301f\u3008\u3041";
        stringArray[997] = "\uc2e7\uc2ec\uc2fb\uc2ec\uc2a3\uc2e1\uc2ec\uc2e3\uc2ea\uc2a3\uc2de\uc2f9\uc2ff\uc2e4\uc2e3\uc2ea\uc2cf\uc2f8\uc2e4\uc2e1\uc2e9\uc2e8\uc2ff\uc2b7\uc2ec\uc2fd\uc2fd\uc2e8\uc2e3\uc2e9\uc2b7\uc2a5\uc2ce\uc2a4\uc2c1\uc2e7\uc2ec\uc2fb\uc2ec\uc2a2\uc2e1\uc2ec\uc2e3\uc2ea\uc2a2\uc2de\uc2f9\uc2ff\uc2e4\uc2e3\uc2ea\uc2cf\uc2f8\uc2e4\uc2e1\uc2e9\uc2e8\uc2ff\uc2b6";
        stringArray[998] = "\u9ad5\u9ade\u9ac9\u9ade\u9a91\u9ad3\u9ade\u9ad1\u9ad8\u9a91\u9aec\u9acb\u9acd\u9ad6\u9ad1\u9ad8\u9afd\u9aca\u9ad6\u9ad3\u9adb\u9ada\u9acd\u9a85\u9ade\u9acf\u9acf\u9ada\u9ad1\u9adb\u9a85\u9a97\u9afc\u9a96\u9af3\u9ad5\u9ade\u9ac9\u9ade\u9a90\u9ad3\u9ade\u9ad1\u9ad8\u9a90\u9aec\u9acb\u9acd\u9ad6\u9ad1\u9ad8\u9afd\u9aca\u9ad6\u9ad3\u9adb\u9ada\u9acd\u9a84";
        stringArray[999] = "\u5697\u569c\u568b\u569c\u56d3\u5691\u569c\u5693\u569a\u56d3\u56ae\u5689\u568f\u5694\u5693\u569a\u56bf\u5688\u5694\u5691\u5699\u5698\u568f\u56c7\u5689\u5692\u56ae\u5689\u568f\u5694\u5693\u569a\u56c7\u56d5\u56d4\u56b1\u5697\u569c\u568b\u569c\u56d2\u5691\u569c\u5693\u569a\u56d2\u56ae\u5689\u568f\u5694\u5693\u569a\u56c6";
        stringArray[1000] = "\u2e7c\u2e77\u2e60\u2e77\u2e38\u2e7a\u2e77\u2e78\u2e71\u2e38\u2e45\u2e62\u2e64\u2e7f\u2e78\u2e71\u2e54\u2e63\u2e7f\u2e7a\u2e72\u2e73\u2e64\u2e2c\u2e77\u2e66\u2e66\u2e73\u2e78\u2e72\u2e2c\u2e3e\u2e5a\u2e7c\u2e77\u2e60\u2e77\u2e39\u2e7a\u2e77\u2e78\u2e71\u2e39\u2e45\u2e62\u2e64\u2e7f\u2e78\u2e71\u2e2d\u2e3f\u2e5a\u2e7c\u2e77\u2e60\u2e77\u2e39\u2e7a\u2e77\u2e78\u2e71\u2e39\u2e45\u2e62\u2e64\u2e7f\u2e78\u2e71\u2e54\u2e63\u2e7f\u2e7a\u2e72\u2e73\u2e64\u2e2d";
        stringArray[1001] = "\uaee0\uaeeb\uaefc\uaeeb\uaea4\uaee6\uaeeb\uaee4\uaeed\uaea4\uaed9\uaefe\uaef8\uaee3\uaee4\uaeed\uaec8\uaeff\uaee3\uaee6\uaeee\uaeef\uaef8\uaeb0\uaeeb\uaefa\uaefa\uaeef\uaee4\uaeee\uaeb0\uaea2\uaec6\uaee0\uaeeb\uaefc\uaeeb\uaea5\uaee6\uaeeb\uaee4\uaeed\uaea5\uaed9\uaefe\uaef8\uaee3\uaee4\uaeed\uaeb1\uaea3\uaec6\uaee0\uaeeb\uaefc\uaeeb\uaea5\uaee6\uaeeb\uaee4\uaeed\uaea5\uaed9\uaefe\uaef8\uaee3\uaee4\uaeed\uaec8\uaeff\uaee3\uaee6\uaeee\uaeef\uaef8\uaeb1";
        stringArray[1002] = "\u62b7\u62bc\u62ab\u62bc\u62f3\u62b1\u62bc\u62b3\u62ba\u62f3\u628e\u62a9\u62af\u62b4\u62b3\u62ba\u629f\u62a8\u62b4\u62b1\u62b9\u62b8\u62af\u62e7\u62bc\u62ad\u62ad\u62b8\u62b3\u62b9\u62e7\u62f5\u6291\u62b7\u62bc\u62ab\u62bc\u62f2\u62b1\u62bc\u62b3\u62ba\u62f2\u628e\u62a9\u62af\u62b4\u62b3\u62ba\u62e6\u62f4\u6291\u62b7\u62bc\u62ab\u62bc\u62f2\u62b1\u62bc\u62b3\u62ba\u62f2\u628e\u62a9\u62af\u62b4\u62b3\u62ba\u629f\u62a8\u62b4\u62b1\u62b9\u62b8\u62af\u62e6";
        stringArray[1003] = "\ufffd\ufff6\uffe1\ufff6\uffb9\ufffb\ufff6\ufff9\ufff0\uffb9\uffc4\uffe3\uffe5\ufffe\ufff9\ufff0\uffd5\uffe2\ufffe\ufffb\ufff3\ufff2\uffe5\uffad\ufff6\uffe7\uffe7\ufff2\ufff9\ufff3\uffad\uffbf\uffd4\uffbe\uffdb\ufffd\ufff6\uffe1\ufff6\uffb8\ufffb\ufff6\ufff9\ufff0\uffb8\uffc4\uffe3\uffe5\ufffe\ufff9\ufff0\uffd5\uffe2\ufffe\ufffb\ufff3\ufff2\uffe5\uffac";
        stringArray[1004] = "\uaefa\uaef1\uaee6\uaef1\uaebe\uaefc\uaef1\uaefe\uaef7\uaebe\uaec3\uaee4\uaee2\uaef9\uaefe\uaef7\uaed2\uaee5\uaef9\uaefc\uaef4\uaef5\uaee2\uaeaa\uaef1\uaee0\uaee0\uaef5\uaefe\uaef4\uaeaa\uaeb8\uaed3\uaeb9\uaedc\uaefa\uaef1\uaee6\uaef1\uaebf\uaefc\uaef1\uaefe\uaef7\uaebf\uaec3\uaee4\uaee2\uaef9\uaefe\uaef7\uaed2\uaee5\uaef9\uaefc\uaef4\uaef5\uaee2\uaeab";
        stringArray[1005] = "\u24ae\u24a5\u24b2\u24a5\u24ea\u24a8\u24a5\u24aa\u24a3\u24ea\u2497\u24b0\u24b6\u24ad\u24aa\u24a3\u2486\u24b1\u24ad\u24a8\u24a0\u24a1\u24b6\u24fe\u24a5\u24b4\u24b4\u24a1\u24aa\u24a0\u24fe\u24ec\u2487\u24ed\u2488\u24ae\u24a5\u24b2\u24a5\u24eb\u24a8\u24a5\u24aa\u24a3\u24eb\u2497\u24b0\u24b6\u24ad\u24aa\u24a3\u2486\u24b1\u24ad\u24a8\u24a0\u24a1\u24b6\u24ff";
        stringArray[1006] = "\u3b64\u3b6f\u3b78\u3b6f\u3b20\u3b62\u3b6f\u3b60\u3b69\u3b20\u3b5d\u3b7a\u3b7c\u3b67\u3b60\u3b69\u3b4c\u3b7b\u3b67\u3b62\u3b6a\u3b6b\u3b7c\u3b34\u3b6f\u3b7e\u3b7e\u3b6b\u3b60\u3b6a\u3b34\u3b26\u3b4d\u3b27\u3b42\u3b64\u3b6f\u3b78\u3b6f\u3b21\u3b62\u3b6f\u3b60\u3b69\u3b21\u3b5d\u3b7a\u3b7c\u3b67\u3b60\u3b69\u3b4c\u3b7b\u3b67\u3b62\u3b6a\u3b6b\u3b7c\u3b35";
        stringArray[1007] = "\ubb37\ubb3c\ubb2b\ubb3c\ubb73\ubb31\ubb3c\ubb33\ubb3a\ubb73\ubb0e\ubb29\ubb2f\ubb34\ubb33\ubb3a\ubb1f\ubb28\ubb34\ubb31\ubb39\ubb38\ubb2f\ubb67\ubb3c\ubb2d\ubb2d\ubb38\ubb33\ubb39\ubb67\ubb75\ubb1e\ubb74\ubb11\ubb37\ubb3c\ubb2b\ubb3c\ubb72\ubb31\ubb3c\ubb33\ubb3a\ubb72\ubb0e\ubb29\ubb2f\ubb34\ubb33\ubb3a\ubb1f\ubb28\ubb34\ubb31\ubb39\ubb38\ubb2f\ubb66";
        stringArray[1008] = "\u6dd2\u6dd9\u6dce\u6dd9\u6d96\u6dd4\u6dd9\u6dd6\u6ddf\u6d96\u6deb\u6dcc\u6dca\u6dd1\u6dd6\u6ddf\u6dfa\u6dcd\u6dd1\u6dd4\u6ddc\u6ddd\u6dca\u6d82\u6dd9\u6dc8\u6dc8\u6ddd\u6dd6\u6ddc\u6d82\u6d90\u6dfb\u6d91\u6df4\u6dd2\u6dd9\u6dce\u6dd9\u6d97\u6dd4\u6dd9\u6dd6\u6ddf\u6d97\u6deb\u6dcc\u6dca\u6dd1\u6dd6\u6ddf\u6dfa\u6dcd\u6dd1\u6dd4\u6ddc\u6ddd\u6dca\u6d83";
        stringArray[1009] = "\u252b\u2520\u2537\u2520\u256f\u252d\u2520\u252f\u2526\u256f\u2512\u2535\u2533\u2528\u252f\u2526\u2503\u2534\u2528\u252d\u2525\u2524\u2533\u257b\u2520\u2531\u2531\u2524\u252f\u2525\u257b\u2569\u2502\u2568\u250d\u252b\u2520\u2537\u2520\u256e\u252d\u2520\u252f\u2526\u256e\u2512\u2535\u2533\u2528\u252f\u2526\u2503\u2534\u2528\u252d\u2525\u2524\u2533\u257a";
        stringArray[1010] = "\uc051\uc05a\uc04d\uc05a\uc015\uc057\uc05a\uc055\uc05c\uc015\uc068\uc04f\uc049\uc052\uc055\uc05c\uc079\uc04e\uc052\uc057\uc05f\uc05e\uc049\uc001\uc04f\uc054\uc068\uc04f\uc049\uc052\uc055\uc05c\uc001\uc013\uc012\uc077\uc051\uc05a\uc04d\uc05a\uc014\uc057\uc05a\uc055\uc05c\uc014\uc068\uc04f\uc049\uc052\uc055\uc05c\uc000";
        stringArray[1011] = "\u2e95\u2e9e\u2e89\u2e9e\u2ed1\u2e93\u2e9e\u2e91\u2e98\u2ed1\u2eac\u2e8b\u2e8d\u2e96\u2e91\u2e98\u2ebd\u2e8a\u2e96\u2e93\u2e9b\u2e9a\u2e8d\u2ec5\u2e9e\u2e8f\u2e8f\u2e9a\u2e91\u2e9b\u2ec5\u2ed7\u2eb3\u2e95\u2e9e\u2e89\u2e9e\u2ed0\u2e93\u2e9e\u2e91\u2e98\u2ed0\u2eac\u2e8b\u2e8d\u2e96\u2e91\u2e98\u2ec4\u2ed6\u2eb3\u2e95\u2e9e\u2e89\u2e9e\u2ed0\u2e93\u2e9e\u2e91\u2e98\u2ed0\u2eac\u2e8b\u2e8d\u2e96\u2e91\u2e98\u2ebd\u2e8a\u2e96\u2e93\u2e9b\u2e9a\u2e8d\u2ec4";
        stringArray[1012] = "\ua95a\ua951\ua946\ua951\ua91e\ua95c\ua951\ua95e\ua957\ua91e\ua963\ua944\ua942\ua959\ua95e\ua957\ua972\ua945\ua959\ua95c\ua954\ua955\ua942\ua90a\ua951\ua940\ua940\ua955\ua95e\ua954\ua90a\ua918\ua973\ua919\ua97c\ua95a\ua951\ua946\ua951\ua91f\ua95c\ua951\ua95e\ua957\ua91f\ua963\ua944\ua942\ua959\ua95e\ua957\ua972\ua945\ua959\ua95c\ua954\ua955\ua942\ua90b";
        stringArray[1013] = "\ucc82\ucc89\ucc9e\ucc89\uccc6\ucc84\ucc89\ucc86\ucc8f\uccc6\uccbb\ucc9c\ucc9a\ucc81\ucc86\ucc8f\uccaa\ucc9d\ucc81\ucc84\ucc8c\ucc8d\ucc9a\uccd2\ucc89\ucc98\ucc98\ucc8d\ucc86\ucc8c\uccd2\uccc0\uccab\uccc1\ucca4\ucc82\ucc89\ucc9e\ucc89\uccc7\ucc84\ucc89\ucc86\ucc8f\uccc7\uccbb\ucc9c\ucc9a\ucc81\ucc86\ucc8f\uccaa\ucc9d\ucc81\ucc84\ucc8c\ucc8d\ucc9a\uccd3";
        stringArray[1014] = "\u2129\u2122\u2135\u2122\u216d\u212f\u2122\u212d\u2124\u216d\u2110\u2137\u2131\u212a\u212d\u2124\u2101\u2136\u212a\u212f\u2127\u2126\u2131\u2179\u2122\u2133\u2133\u2126\u212d\u2127\u2179\u216b\u2100\u216a\u210f\u2129\u2122\u2135\u2122\u216c\u212f\u2122\u212d\u2124\u216c\u2110\u2137\u2131\u212a\u212d\u2124\u2101\u2136\u212a\u212f\u2127\u2126\u2131\u2178";
        stringArray[1015] = "\ucdc9\ucdc2\ucdd5\ucdc2\ucd8d\ucdcf\ucdc2\ucdcd\ucdc4\ucd8d\ucdf0\ucdd7\ucdd1\ucdca\ucdcd\ucdc4\ucde1\ucdd6\ucdca\ucdcf\ucdc7\ucdc6\ucdd1\ucd99\ucdc2\ucdd3\ucdd3\ucdc6\ucdcd\ucdc7\ucd99\ucd8b\ucde0\ucd8a\ucdef\ucdc9\ucdc2\ucdd5\ucdc2\ucd8c\ucdcf\ucdc2\ucdcd\ucdc4\ucd8c\ucdf0\ucdd7\ucdd1\ucdca\ucdcd\ucdc4\ucde1\ucdd6\ucdca\ucdcf\ucdc7\ucdc6\ucdd1\ucd98";
        stringArray[1016] = "\u0efc\u0ef7\u0ee0\u0ef7\u0eb8\u0efa\u0ef7\u0ef8\u0ef1\u0eb8\u0ec5\u0ee2\u0ee4\u0eff\u0ef8\u0ef1\u0ed4\u0ee3\u0eff\u0efa\u0ef2\u0ef3\u0ee4\u0eac\u0ef7\u0ee6\u0ee6\u0ef3\u0ef8\u0ef2\u0eac\u0ebe\u0ed5\u0ebf\u0eda\u0efc\u0ef7\u0ee0\u0ef7\u0eb9\u0efa\u0ef7\u0ef8\u0ef1\u0eb9\u0ec5\u0ee2\u0ee4\u0eff\u0ef8\u0ef1\u0ed4\u0ee3\u0eff\u0efa\u0ef2\u0ef3\u0ee4\u0ead";
        stringArray[1017] = "\u0a7e\u0a75\u0a62\u0a75\u0a3a\u0a78\u0a75\u0a7a\u0a73\u0a3a\u0a47\u0a60\u0a66\u0a7d\u0a7a\u0a73\u0a56\u0a61\u0a7d\u0a78\u0a70\u0a71\u0a66\u0a2e\u0a75\u0a64\u0a64\u0a71\u0a7a\u0a70\u0a2e\u0a3c\u0a57\u0a3d\u0a58\u0a7e\u0a75\u0a62\u0a75\u0a3b\u0a78\u0a75\u0a7a\u0a73\u0a3b\u0a47\u0a60\u0a66\u0a7d\u0a7a\u0a73\u0a56\u0a61\u0a7d\u0a78\u0a70\u0a71\u0a66\u0a2f";
