        stringArray[1066] = "\u959a\u9591\u9586\u9591\u95de\u959c\u9591\u959e\u9597\u95de\u95a3\u9584\u9582\u9599\u959e\u9597\u95b2\u9585\u9599\u959c\u9594\u9595\u9582\u95ca\u9591\u9580\u9580\u9595\u959e\u9594\u95ca\u95d8\u95b3\u95d9\u95bc\u959a\u9591\u9586\u9591\u95df\u959c\u9591\u959e\u9597\u95df\u95a3\u9584\u9582\u9599\u959e\u9597\u95b2\u9585\u9599\u959c\u9594\u9595\u9582\u95cb";
        stringArray[1067] = "\u2fd3\u2fd8\u2fcf\u2fd8\u2f97\u2fd5\u2fd8\u2fd7\u2fde\u2f97\u2fea\u2fcd\u2fcb\u2fd0\u2fd7\u2fde\u2ffb\u2fcc\u2fd0\u2fd5\u2fdd\u2fdc\u2fcb\u2f83\u2fd8\u2fc9\u2fc9\u2fdc\u2fd7\u2fdd\u2f83\u2f91\u2ffa\u2f90\u2ff5\u2fd3\u2fd8\u2fcf\u2fd8\u2f96\u2fd5\u2fd8\u2fd7\u2fde\u2f96\u2fea\u2fcd\u2fcb\u2fd0\u2fd7\u2fde\u2ffb\u2fcc\u2fd0\u2fd5\u2fdd\u2fdc\u2fcb\u2f82";
        stringArray[1068] = "\u1e47\u1e4c\u1e5b\u1e4c\u1e03\u1e41\u1e4c\u1e43\u1e4a\u1e03\u1e7e\u1e59\u1e5f\u1e44\u1e43\u1e4a\u1e6f\u1e58\u1e44\u1e41\u1e49\u1e48\u1e5f\u1e17\u1e4c\u1e5d\u1e5d\u1e48\u1e43\u1e49\u1e17\u1e05\u1e6e\u1e04\u1e61\u1e47\u1e4c\u1e5b\u1e4c\u1e02\u1e41\u1e4c\u1e43\u1e4a\u1e02\u1e7e\u1e59\u1e5f\u1e44\u1e43\u1e4a\u1e6f\u1e58\u1e44\u1e41\u1e49\u1e48\u1e5f\u1e16";
        stringArray[1069] = "\u6d26\u6d2d\u6d3a\u6d2d\u6d62\u6d20\u6d2d\u6d22\u6d2b\u6d62\u6d1f\u6d38\u6d3e\u6d25\u6d22\u6d2b\u6d0e\u6d39\u6d25\u6d20\u6d28\u6d29\u6d3e\u6d76\u6d2d\u6d3c\u6d3c\u6d29\u6d22\u6d28\u6d76\u6d64\u6d0f\u6d65\u6d00\u6d26\u6d2d\u6d3a\u6d2d\u6d63\u6d20\u6d2d\u6d22\u6d2b\u6d63\u6d1f\u6d38\u6d3e\u6d25\u6d22\u6d2b\u6d0e\u6d39\u6d25\u6d20\u6d28\u6d29\u6d3e\u6d77";
        stringArray[1070] = "\u60fb\u60f0\u60e7\u60f0\u60bf\u60fd\u60f0\u60ff\u60f6\u60bf\u60c2\u60e5\u60e3\u60f8\u60ff\u60f6\u60d3\u60e4\u60f8\u60fd\u60f5\u60f4\u60e3\u60ab\u60e5\u60fe\u60c2\u60e5\u60e3\u60f8\u60ff\u60f6\u60ab\u60b9\u60b8\u60dd\u60fb\u60f0\u60e7\u60f0\u60be\u60fd\u60f0\u60ff\u60f6\u60be\u60c2\u60e5\u60e3\u60f8\u60ff\u60f6\u60aa";
        stringArray[1071] = "\u8bab\u8ba0\u8bb7\u8ba0\u8bef\u8bad\u8ba0\u8baf\u8ba6\u8bef\u8b92\u8bb5\u8bb3\u8ba8\u8baf\u8ba6\u8b83\u8bb4\u8ba8\u8bad\u8ba5\u8ba4\u8bb3\u8bfb\u8ba0\u8bb1\u8bb1\u8ba4\u8baf\u8ba5\u8bfb\u8be9\u8b8d\u8bab\u8ba0\u8bb7\u8ba0\u8bee\u8bad\u8ba0\u8baf\u8ba6\u8bee\u8b92\u8bb5\u8bb3\u8ba8\u8baf\u8ba6\u8bfa\u8be8\u8b8d\u8bab\u8ba0\u8bb7\u8ba0\u8bee\u8bad\u8ba0\u8baf\u8ba6\u8bee\u8b92\u8bb5\u8bb3\u8ba8\u8baf\u8ba6\u8b83\u8bb4\u8ba8\u8bad\u8ba5\u8ba4\u8bb3\u8bfa";
        stringArray[1072] = "\u2808\u2803\u2814\u2803\u284c\u280e\u2803\u280c\u2805\u284c\u2831\u2816\u2810\u280b\u280c\u2805\u2820\u2817\u280b\u280e\u2806\u2807\u2810\u2858\u2816\u280d\u2831\u2816\u2810\u280b\u280c\u2805\u2858\u284a\u284b\u282e\u2808\u2803\u2814\u2803\u284d\u280e\u2803\u280c\u2805\u284d\u2831\u2816\u2810\u280b\u280c\u2805\u2859";
        stringArray[1073] = "\u1d22\u1d29\u1d3e\u1d29\u1d66\u1d24\u1d29\u1d26\u1d2f\u1d66\u1d1b\u1d3c\u1d3a\u1d21\u1d26\u1d2f\u1d0a\u1d3d\u1d21\u1d24\u1d2c\u1d2d\u1d3a\u1d72\u1d29\u1d38\u1d38\u1d2d\u1d26\u1d2c\u1d72\u1d60\u1d04\u1d22\u1d29\u1d3e\u1d29\u1d67\u1d24\u1d29\u1d26\u1d2f\u1d67\u1d1b\u1d3c\u1d3a\u1d21\u1d26\u1d2f\u1d73\u1d61\u1d04\u1d22\u1d29\u1d3e\u1d29\u1d67\u1d24\u1d29\u1d26\u1d2f\u1d67\u1d1b\u1d3c\u1d3a\u1d21\u1d26\u1d2f\u1d0a\u1d3d\u1d21\u1d24\u1d2c\u1d2d\u1d3a\u1d73";
