        stringArray[1076] = "\uc125\uc12e\uc139\uc12e\uc161\uc123\uc12e\uc121\uc128\uc161\uc11c\uc13b\uc13d\uc126\uc121\uc128\uc10d\uc13a\uc126\uc123\uc12b\uc12a\uc13d\uc175\uc12e\uc13f\uc13f\uc12a\uc121\uc12b\uc175\uc167\uc10c\uc166\uc103\uc125\uc12e\uc139\uc12e\uc160\uc123\uc12e\uc121\uc128\uc160\uc11c\uc13b\uc13d\uc126\uc121\uc128\uc10d\uc13a\uc126\uc123\uc12b\uc12a\uc13d\uc174";
