        stringArray[1078] = "\ucb23\ucb28\ucb3f\ucb28\ucb67\ucb25\ucb28\ucb27\ucb2e\ucb67\ucb1a\ucb3d\ucb3b\ucb20\ucb27\ucb2e\ucb0b\ucb3c\ucb20\ucb25\ucb2d\ucb2c\ucb3b\ucb73\ucb28\ucb39\ucb39\ucb2c\ucb27\ucb2d\ucb73\ucb61\ucb0a\ucb60\ucb05\ucb23\ucb28\ucb3f\ucb28\ucb66\ucb25\ucb28\ucb27\ucb2e\ucb66\ucb1a\ucb3d\ucb3b\ucb20\ucb27\ucb2e\ucb0b\ucb3c\ucb20\ucb25\ucb2d\ucb2c\ucb3b\ucb72";
