        stringArray[1414] = "\ubc4b\ubc40\ubc57\ubc40\ubc0f\ubc4d\ubc40\ubc4f\ubc46\ubc0f\ubc72\ubc55\ubc53\ubc48\ubc4f\ubc46\ubc63\ubc54\ubc48\ubc4d\ubc45\ubc44\ubc53\ubc1b\ubc55\ubc4e\ubc72\ubc55\ubc53\ubc48\ubc4f\ubc46\ubc1b\ubc09\ubc08\ubc6d\ubc4b\ubc40\ubc57\ubc40\ubc0e\ubc4d\ubc40\ubc4f\ubc46\ubc0e\ubc72\ubc55\ubc53\ubc48\ubc4f\ubc46\ubc1a";
        stringArray[1415] = "\u62ce\u6290\u62cb\u6290\u6282\u62e6\u62c0\u62cb\u62dc\u62cb\u6285\u62c6\u62cb\u62c4\u62cd\u6285\u62f9\u62de\u62d8\u62c3\u62c4\u62cd\u6291\u62e3\u6283\u62fc";
