        stringArray[1420] = "\ub51f\ub514\ub503\ub514\ub55b\ub519\ub514\ub51b\ub512\ub55b\ub526\ub501\ub507\ub51c\ub51b\ub512\ub537\ub500\ub51c\ub519\ub511\ub510\ub507\ub54f\ub514\ub505\ub505\ub510\ub51b\ub511\ub54f\ub55d\ub539\ub51f\ub514\ub503\ub514\ub55a\ub519\ub514\ub51b\ub512\ub55a\ub526\ub501\ub507\ub51c\ub51b\ub512\ub54e\ub55c\ub539\ub51f\ub514\ub503\ub514\ub55a\ub519\ub514\ub51b\ub512\ub55a\ub526\ub501\ub507\ub51c\ub51b\ub512\ub537\ub500\ub51c\ub519\ub511\ub510\ub507\ub54e";
