        stringArray[1477] = "\u3245\u324e\u3259\u324e\u3201\u3243\u324e\u3241\u3248\u3201\u327c\u325b\u325d\u3246\u3241\u3248\u326d\u325a\u3246\u3243\u324b\u324a\u325d\u3215\u325b\u3240\u327c\u325b\u325d\u3246\u3241\u3248\u3215\u3207\u3206\u3263\u3245\u324e\u3259\u324e\u3200\u3243\u324e\u3241\u3248\u3200\u327c\u325b\u325d\u3246\u3241\u3248\u3214";
        stringArray[1478] = "\u45d0\u45db\u45cc\u45db\u4594\u45d6\u45db\u45d4\u45dd\u4594\u45e9\u45ce\u45c8\u45d3\u45d4\u45dd\u45f8\u45cf\u45d3\u45d6\u45de\u45df\u45c8\u4580\u45db\u45ca\u45ca\u45df\u45d4\u45de\u4580\u4592\u45f6\u45d0\u45db\u45cc\u45db\u4595\u45d6\u45db\u45d4\u45dd\u4595\u45e9\u45ce\u45c8\u45d3\u45d4\u45dd\u4581\u4593\u45f6\u45d0\u45db\u45cc\u45db\u4595\u45d6\u45db\u45d4\u45dd\u4595\u45e9\u45ce\u45c8\u45d3\u45d4\u45dd\u45f8\u45cf\u45d3\u45d6\u45de\u45df\u45c8\u4581";
