        stringArray[2139] = "\u742e\u7425\u7432\u7425\u746a\u7428\u7425\u742a\u7423\u746a\u7417\u7430\u7436\u742d\u742a\u7423\u7406\u7431\u742d\u7428\u7420\u7421\u7436\u747e\u7425\u7434\u7434\u7421\u742a\u7420\u747e\u746c\u7407\u746d\u7408\u742e\u7425\u7432\u7425\u746b\u7428\u7425\u742a\u7423\u746b\u7417\u7430\u7436\u742d\u742a\u7423\u7406\u7431\u742d\u7428\u7420\u7421\u7436\u747f";
        stringArray[2140] = "\uc2b5\uc2be\uc2a9\uc2be\uc2f1\uc2b3\uc2be\uc2b1\uc2b8\uc2f1\uc28c\uc2ab\uc2ad\uc2b6\uc2b1\uc2b8\uc29d\uc2aa\uc2b6\uc2b3\uc2bb\uc2ba\uc2ad\uc2e5\uc2be\uc2af\uc2af\uc2ba\uc2b1\uc2bb\uc2e5\uc2f7\uc29c\uc2f6\uc293\uc2b5\uc2be\uc2a9\uc2be\uc2f0\uc2b3\uc2be\uc2b1\uc2b8\uc2f0\uc28c\uc2ab\uc2ad\uc2b6\uc2b1\uc2b8\uc29d\uc2aa\uc2b6\uc2b3\uc2bb\uc2ba\uc2ad\uc2e4";
