        stringArray[2231] = "\u9126\u912d\u913a\u912d\u9162\u9139\u9138\u9125\u9120\u9162\u910e\u912d\u913f\u9129\u917a\u9178\u9168\u9109\u9122\u912f\u9123\u9128\u9129\u913e\u9176\u913b\u9125\u9138\u9124\u9123\u9139\u9138\u911c\u912d\u9128\u9128\u9125\u9122\u912b\u9176\u9164\u9165\u9100\u9126\u912d\u913a\u912d\u9163\u9139\u9138\u9125\u9120\u9163\u910e\u912d\u913f\u9129\u917a\u9178\u9168\u9109\u9122\u912f\u9123\u9128\u9129\u913e\u9177";
